<?php $cats=db()->query('SELECT * FROM categories WHERE is_active=1 ORDER BY name')->fetchAll();?><form method="post" enctype="multipart/form-data" class="card-form product-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Fish name<input name="name" value="<?=e($p['name']??'')?>" required maxlength="140"></label><label>Category<select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($p['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Description<textarea name="description" required><?=e($p['description']??'')?></textarea></label><div class="form-row"><label>Price per kg (₹)<input type="number" name="price" step="0.01" min="1" value="<?=e($p['price']??'')?>" required></label><label>Available stock (kg)<input type="number" name="stock" step="0.5" min="0" value="<?=e($p['stock']??'')?>" required></label></div><div class="form-row"><label>Minimum order (kg)<input type="number" name="min_quantity" step="0.5" min="0.5" value="<?=e($p['min_quantity']??1)?>" required></label><label>Freshness note<input name="freshness_info" value="<?=e($p['freshness_info']??'')?>" placeholder="Landed this morning"></label></div><label>Product image <small>JPG, PNG or WebP — max 2 MB</small><input type="file" name="image" accept="image/jpeg,image/png,image/webp" data-preview></label><?php if(!empty($p['image_path'])):?><img class="preview" src="<?=url($p['image_path'])?>" alt="Current product image"><label class="check"><input type="checkbox" name="remove_image"> Remove current uploaded image</label><?php else:?><img class="preview" src="" alt="" hidden><?php endif;?><label class="check"><input type="checkbox" name="is_available" <?=!isset($p)||$p['is_available']?'checked':''?>> Available to buyers</label><button><?=isset($p)?'Save changes':'Publish listing'?></button></form>
